ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{jsonrpc: "2.0", id: 1, method: "initialize", params: {
    protocolVersion: "2025-06-18",
    capabilities: {},
    clientInfo: {name: "munit-test", version: "1.0"}
}}

%dw 2.0
output application/java
---
if (payload is String) do {
    var lines = (payload as String) splitBy "\n"
    var dataLine = (lines filter ($ startsWith "data:"))[0] default ""
    var jsonStr = if (dataLine != "") dataLine[5 to -1] else (payload as String)
    ---
    read(jsonStr, "application/json")
} else payload

%dw 2.0
output application/java
var getOrderStatusSchema = {
    "type": "object",
    "properties": {"orderId": {"type": "string", "description": "Unique order identifier, for example ORD-1001.", "minLength": 1}},
    "required": ["orderId"],
    "additionalProperties": false
}
var getShippingEtaSchema = {
    "type": "object",
    "properties": {"orderId": {"type": "string", "description": "Unique order identifier, for example ORD-1001.", "minLength": 1}},
    "required": ["orderId"],
    "additionalProperties": false
}
---
{
    getOrderStatusOrderIdRequired: (getOrderStatusSchema.required) contains "orderId",
    getShippingEtaOrderIdRequired: (getShippingEtaSchema.required) contains "orderId"
}
